function loadData() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : structuredClone(seedData);
  } catch { return structuredClone(seedData); }
}
function persist() { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); }
function t(key, vars = {}) {
  const language = currentLanguage();
  let value = translations[language]?.[key] || translations.en[key] || key;
  Object.entries(vars).forEach(([name, replacement]) => { value = value.replaceAll(`{${name}}`, replacement); });
  return value;
}
function currentLanguage() { return ui.session ? currentUser()?.language || 'en' : ui.homeLanguage || 'en'; }
function cropName(crop) { return cropTranslations[crop]?.[currentLanguage()] || cropTranslations[crop]?.en || crop; }
function currentUser() { return data.users.find(user => user.id === ui.session?.userId); }
function currentFarmer() { return ui.session?.role === 'farmer' ? currentUser() : null; }
function currentCentreUser() { return ui.session?.role === 'centre' ? currentUser() : null; }
function currentCentre() { const user = currentCentreUser(); return data.centres.find(centre => centre.id === user?.centreId); }
function getCentre(id) { return data.centres.find(centre => centre.id === id); }
function escapeHTML(value) { return String(value ?? '').replace(/[&<>'"]/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[char])); }
function initials(name = '') { return name.split(' ').map(word => word[0]).join('').slice(0, 2).toUpperCase(); }
function money(value) { return new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value || 0); }
function formatDate(value) { return new Intl.DateTimeFormat('en-IN', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(`${value}T12:00:00`)); }
function timeAgo(value) { const hours = Math.max(1, Math.floor((Date.now() - new Date(value).getTime()) / 3600000)); return hours < 24 ? `${hours}h ago` : `${Math.floor(hours / 24)}d ago`; }
function haversine(a, b) { const rad = d => d * Math.PI / 180; const R = 6371; const dLat = rad(b.lat - a.lat); const dLon = rad(b.lng - a.lng); const q = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLon / 2) ** 2; return Math.round(R * 2 * Math.atan2(Math.sqrt(q), Math.sqrt(1 - q)) * 10) / 10; }
function calculateRate(crop, grade = 'Common') { return data.rates.find(rate => rate.crop === crop && rate.grade === grade)?.rate || data.rates.find(rate => rate.crop === crop)?.rate || 0; }
function queueClass(condition) { return condition === 'high' ? 'high' : condition === 'moderate' ? 'moderate' : 'low'; }
function badge(condition, label) { return `<span class="badge ${queueClass(condition)}">${escapeHTML(label || t(condition))}</span>`; }
function getAvailableHolding(centre) { return Math.max(0, centre.holdingCapacity - centre.currentHolding); }
function isStorageNeeded(centre, quantity) { return quantity > getAvailableHolding(centre) && (centre.queueCondition === 'high' || quantity >= 75); }
function priority(centre, distance) { return centre.queueCondition === 'high' && distance >= 18 ? 'earlier' : 'normal'; }
function priorityMessage(centre, distance) {
  if (priority(centre, distance) === 'earlier') return `You are approximately ${distance.toFixed(1)} km from this centre and the current queue is high. AgriConnect recommends an earlier suitable slot to reduce your long-distance travel burden.`;
  if (centre.queueCondition === 'moderate') return `AgriConnect considers your approximate ${distance.toFixed(1)} km travel distance, the current queue and available slots when suggesting a suitable visit time.`;
  return `This recommendation balances your approximate ${distance.toFixed(1)} km travel distance, current queue conditions and available slots.`;
}
function translateDynamic(type, fallback) {
  const lang = currentLanguage();
  const messages = {
    distance: { te: 'ప్రస్తుత క్యూ మరియు మీ ప్రయాణ దూరం ఆధారంగా సరైన స్లాట్ సూచించబడింది.', hi: 'वर्तमान कतार और आपकी यात्रा दूरी के आधार पर उपयुक्त स्लॉट सुझाया गया है।', ta: 'தற்போதைய வரிசை மற்றும் பயண தூரத்தின் அடிப்படையில் பொருத்தமான இடம் பரிந்துரைக்கப்படுகிறது.', kn: 'ಪ್ರಸ್ತುತ ಸರತಿ ಮತ್ತು ನಿಮ್ಮ ಪ್ರಯಾಣ ದೂರದ ಆಧಾರದ ಮೇಲೆ ಸೂಕ್ತ ಸ್ಲಾಟ್ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.', ml: 'നിലവിലെ ക്യൂവും യാത്രാ ദൂരവും കണക്കിലെടുത്ത് അനുയോജ്യമായ സ്ലോട്ട് ശുപാർശ ചെയ്യുന്നു.', mr: 'सध्याची रांग आणि प्रवासाचे अंतर लक्षात घेऊन योग्य स्लॉट सुचवला आहे.', bn: 'বর্তমান সারি ও ভ্রমণের দূরত্ব অনুযায়ী উপযুক্ত স্লট প্রস্তাব করা হয়েছে।' },
    storage: { te: 'మీ పంటకు సరిపోయే సమీప నిల్వ అందుబాటులో ఉంది.', hi: 'आपकी फसल के लिए उपयुक्त पास का भंडारण उपलब्ध है।', ta: 'உங்கள் பயிருக்கு ஏற்ற அருகிலுள்ள சேமிப்பு உள்ளது.', kn: 'ನಿಮ್ಮ ಬೆಳೆಗೆ ಸೂಕ್ತವಾದ ಸಮೀಪದ ಸಂಗ್ರಹಣೆ ಲಭ್ಯವಿದೆ.', ml: 'നിങ്ങളുടെ വിളയ്ക്ക് അനുയോജ്യമായ സമീപ സംഭരണം ലഭ്യമാണ്.', mr: 'तुमच्या पिकासाठी योग्य जवळची साठवण उपलब्ध आहे.', bn: 'আপনার ফসলের জন্য উপযুক্ত কাছের সংরক্ষণ উপলব্ধ।' }
  };
  return messages[type]?.[lang] || fallback;
}

function render() {
  const root = document.getElementById('app');
  if (!ui.session) root.innerHTML = ui.route === 'auth' ? renderAuth() : renderHome();
  else root.innerHTML = renderShell();
  document.documentElement.lang = currentLanguage();
}

function renderBrand() { return `<span class="brand"><span class="agri">Agri</span><span class="connect">Connect</span></span>`; }
function languageOptions(selected) { return Object.entries(languages).map(([code, name]) => `<option value="${code}" ${code === selected ? 'selected' : ''}>${name}</option>`).join(''); }

function renderHome() {
  return `<main class="landing">
    <header class="site-header"><div class="site-header-inner">
      <a href="#top" aria-label="AgriConnect home">${renderBrand()}</a>
      <nav class="site-nav"><a href="#about">${t('about')}</a><a href="#features">${t('features')}</a><a href="#how">${t('howItWorks')}</a><a href="#contact">${t('contact')}</a></nav>
      <div class="header-actions"><select class="language-select" aria-label="${t('language')}" data-home-language>${languageOptions(currentLanguage())}</select><button class="button button-outline button-sm" data-action="start-auth" data-role="centre" data-mode="login">${t('centreLogin')}</button><button class="button button-primary button-sm" data-action="start-auth" data-role="farmer" data-mode="login">${t('farmerLogin')}</button></div>
    </div></header>
    <section class="hero" id="top"><div class="hero-grid">
      <div><span class="eyebrow">Procurement, made clear</span><h1>Plan your procurement visit with <span>clearer information.</span></h1><p class="hero-copy">Find suitable procurement centres, understand queue conditions, book available slots, view MSP information and receive payment updates — all in one place.</p>
      <div class="hero-actions"><button class="button button-primary" data-action="start-auth" data-role="farmer" data-mode="login">${t('farmerLogin')} <span>→</span></button><button class="button button-outline" data-action="start-auth" data-role="farmer" data-mode="register">${t('registerFarmer')}</button></div>
      <div class="trust-row"><div class="trust-item"><span class="trust-mark">✓</span> No Aadhaar required</div><div class="trust-item"><span class="trust-mark">✓</span> Phone OTP sign-in</div><div class="trust-item"><span class="trust-mark">✓</span> 8 Indian languages</div></div></div>
      <aside class="hero-panel" aria-label="AgriConnect dashboard preview"><div class="panel-top"><div class="panel-greeting">Good morning<strong>Anitha Reddy</strong></div><div class="avatar">AR</div></div><div class="booking-preview"><span class="small">YOUR RECOMMENDED VISIT</span><div class="booking-time">18 Sep · 10:00 AM</div><div class="booking-meta"><span>Raghavapuram Centre</span><span>32.4 km away</span></div></div><div class="mini-grid"><div class="mini-card"><div class="mini-icon">↗</div><strong>Earlier slot</strong><span>Distance-aware suggestion</span></div><div class="mini-card"><div class="mini-icon">▣</div><strong>Storage nearby</strong><span>150 quintals available</span></div></div></aside>
    </div></section>
    <section class="stat-strip"><div><strong>Distance-aware</strong><span>Travel burden considered</span></div><div><strong>Centre-ready</strong><span>Queue and slot visibility</span></div><div><strong>Storage support</strong><span>When capacity is limited</span></div><div><strong>Farmer-first</strong><span>Clear, simple guidance</span></div></section>
    <section class="section" id="about"><div class="section-title"><span class="eyebrow">One connected experience</span><h2>Clearer decisions from field to procurement centre.</h2><p>AgriConnect helps farmers plan before they travel. It provides preliminary information and scheduling support, while final procurement decisions stay with the applicable authority.</p></div><div class="feature-grid" id="features">
      ${feature('⌖', 'Find suitable centres', 'Compare crop support, availability, distance and queue conditions.')}
      ${feature('◷', 'Distance-aware scheduling', 'Longer journeys receive thoughtful scheduling support when queues are high.')}
      ${feature('▤', 'Procurement slot booking', 'Choose an available visit window and get a clear booking summary.')}
      ${feature('₹', 'MSP & estimated value', 'Understand configured demo rates and estimate your procurement value.')}
      ${feature('▣', 'Nearby storage recommendations', 'See crop-compatible options when immediate holding capacity is limited.')}
      ${feature('◉', 'Payment notifications', 'Receive updates when a centre marks a payment as credited.')}
      ${feature('◫', 'Procurement history', 'Keep your own procurement information in one easy place.')}
      ${feature('अ', 'Multilingual support', 'Use AgriConnect in the language that feels most comfortable.')}
    </div></section>
    <section class="callout-section" id="how"><div class="callout"><div class="callout-copy"><span class="eyebrow" style="color:#ffad74">Thoughtful planning, not an official rule</span><h2>Smart recommendations that explain themselves.</h2><p>We combine approximate travel distance with crop support, centre availability, queue conditions and slots. When a long trip meets a high queue, AgriConnect can suggest an earlier suitable visit time.</p><button class="button button-orange" data-action="start-auth" data-role="farmer" data-mode="login">Start planning your visit</button></div><div class="callout-points"><div class="callout-point"><span>01</span> Your approximate travel distance is calculated from actual coordinates.</div><div class="callout-point"><span>02</span> Centre availability and current queue conditions are considered together.</div><div class="callout-point"><span>03</span> Crop-compatible nearby storage is shown only when it could be useful.</div></div></div></section>
    <footer class="site-footer" id="contact"><div class="footer-line">${renderBrand()}<span class="footer-copy">AgriConnect provides preliminary information and scheduling support. Final procurement eligibility, acceptance, quality assessment, quantity and payment remain subject to applicable procurement authorities and official rules.</span></div></footer>
  </main>`;
}
function feature(icon, title, text) { return `<article class="feature-card"><div class="feature-icon">${icon}</div><h3>${title}</h3><p>${text}</p></article>`; }

function renderAuth() {
  const auth = ui.auth; const isCentre = auth.role === 'centre'; const isRegister = auth.mode === 'register';
  const title = isRegister ? (isCentre ? 'Create your centre account' : 'Create your farmer account') : (isCentre ? 'Welcome, centre operator' : 'Welcome back, farmer');
  const subtitle = isRegister ? 'Verify your mobile number, then add a few details to begin.' : 'Use your mobile number to receive a one-time password.';
  let fields = '';
  if (auth.step === 1) fields = `<form data-form="send-otp"><div class="form-field"><label>${t('mobileNumber')}</label><div class="input-prefix"><span>+91</span><input name="mobile" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" required value="${escapeHTML(auth.mobile)}" placeholder="10-digit mobile number" /></div></div><div class="auth-actions"><button class="button button-primary" type="submit">${t('sendOtp')} <span>→</span></button></div></form>`;
  if (auth.step === 2) fields = `<form data-form="verify-otp"><div class="form-field"><label>${t('otp')}</label><input class="otp-input" name="otp" inputmode="numeric" maxlength="6" placeholder="••••••" required /></div><p class="demo-otp">Demo OTP: <strong>123456</strong>. No message is sent in this prototype.</p><div class="auth-actions"><button class="button button-primary" type="submit">${t('verifyOtp')} <span>→</span></button><button class="button button-ghost" type="button" data-action="auth-back">Change mobile number</button></div></form>`;
  if (auth.step === 3) fields = renderRegistrationDetails(isCentre);
  return `<main class="auth-page"><aside class="auth-aside"><a href="#" data-action="go-home">${renderBrand()}</a><div class="auth-aside-content"><span class="eyebrow" style="color:#ffad74">PROCUREMENT, MADE CLEAR</span><h1>Plan with confidence before you travel.</h1><p>One clear place for centre conditions, suitable visit times, payment updates and storage support.</p><div class="auth-benefits"><div class="auth-benefit"><b>✓</b> Distance-aware recommendations</div><div class="auth-benefit"><b>✓</b> Nearby storage support</div><div class="auth-benefit"><b>✓</b> Your information stays connected</div></div></div></aside><section class="auth-main"><button class="auth-toplink button button-ghost" data-action="go-home">← ${t('home')}</button><div class="auth-form-wrap"><span class="eyebrow">${isRegister ? t('registration') : t('login')} · ${isCentre ? t('operator') : t('farmer')}</span><h2>${title}</h2><p>${subtitle}</p><div class="progress-dots">${[1,2,3].map(step => `<span class="${step <= auth.step ? 'active' : ''}"></span>`).join('')}</div>${fields}<p class="auth-foot">${isRegister ? 'Already have an account?' : "Don't have an account?"} <button class="text-link button button-ghost" data-action="toggle-auth-mode">${isRegister ? t('login') : (isCentre ? 'Register as centre' : t('registerFarmer'))}</button></p><p class="auth-foot">${isCentre ? 'Farmer account?' : 'Centre operator?'} <button class="text-link button button-ghost" data-action="switch-auth-role">${isCentre ? t('farmerLogin') : t('centreLogin')}</button></p></div></section></main>`;
}
function renderRegistrationDetails(isCentre) {
  if (isCentre) return `<form data-form="register-centre"><div class="form-field"><label>${t('centreName')}</label><input name="centreName" required placeholder="e.g. Krishna Market Procurement Centre" /></div><div class="form-field"><label>${t('operatorName')}</label><input name="operatorName" required placeholder="Your full name" /></div><div class="field-grid"><div class="form-field"><label>${t('village')}</label><input name="village" required placeholder="Village / location" /></div><div class="form-field"><label>${t('district')}</label><input name="district" required placeholder="District" /></div></div><div class="form-field"><label>Centre type</label><select name="centreType"><option>Government Procurement Centre</option><option>Agricultural Market Yard</option></select></div><div class="auth-actions"><button class="button button-primary" type="submit">Create centre account <span>→</span></button></div></form>`;
  return `<form data-form="register-farmer"><div class="form-field"><label>${t('farmerName')}</label><input name="name" required placeholder="Your full name" /></div><div class="field-grid"><div class="form-field"><label>${t('village')}</label><input name="village" required placeholder="Your village" /></div><div class="form-field"><label>${t('district')}</label><input name="district" required placeholder="Your district" /></div></div><div class="form-field"><label>${t('language')}</label><select name="language">${languageOptions('en')}</select></div><div class="auth-actions"><button class="button button-primary" type="submit">Create farmer account <span>→</span></button></div></form>`;
}

function renderShell() {
  const isFarmer = ui.session.role === 'farmer';
  const user = currentUser();
  const unread = isFarmer ? data.notifications.filter(item => item.farmerId === user.id && !item.read).length : 0;
  const page = isFarmer ? renderFarmerPage() : renderOperatorPage();
  const pageTitle = routeTitle(ui.route);
  return `<div class="app-shell"><aside class="sidebar ${ui.mobileSidebar ? 'open' : ''}">
    ${renderBrand()}<div class="side-role">${isFarmer ? t('farmer') : t('operator')} portal</div>
    <nav class="side-nav">${isFarmer ? farmerNav() : centreNav()}</nav>
    <div class="sidebar-bottom"><button class="side-nav-button side-nav button" data-action="logout"><span class="nav-icon">⇥</span>${t('logout')}</button></div>
  </aside><main class="app-main"><header class="app-topbar"><div class="topbar-left"><button class="mobile-menu" aria-label="Menu" data-action="toggle-menu">☰</button><span class="page-crumb">AgriConnect&nbsp; / &nbsp;<strong>${escapeHTML(pageTitle)}</strong></span></div><div class="topbar-actions">${isFarmer ? `<button class="icon-button" aria-label="${t('notifications')}" data-route="notifications">◌${unread ? '<i class="notification-dot"></i>' : ''}</button>` : ''}<select class="language-select" aria-label="${t('language')}" data-app-language>${languageOptions(currentLanguage())}</select><div class="user-chip"><div class="chip-avatar">${initials(user.name || user.operatorName)}</div><div><strong>${escapeHTML(user.name || user.operatorName)}</strong><span>${isFarmer ? user.farmerId : 'Centre operator'}</span></div></div></div></header>${page}</main></div>${renderModal()}`;
}
function routeTitle(route) {
  const items = { dashboard: t('dashboard'), finder: t('findCentre'), 'centre-details': t('centreInfo'), msp: t('msp'), 'procurement-information': t('procurementInformation'), payment: t('payment'), history: t('history'), notifications: t('notifications'), profile: t('profile'), 'centre-dashboard': t('dashboard'), 'centre-info': t('centreInfo'), bookings: t('farmerBookings'), 'centre-payments': t('paymentUpdates'), rates: t('procurementRates') };
  return items[route] || t('dashboard');
}
function navButton(route, icon, label) { return `<button class="${ui.route === route ? 'active' : ''}" data-route="${route}"><span class="nav-icon">${icon}</span>${label}</button>`; }
function farmerNav() { return `${navButton('dashboard','▦',t('dashboard'))}${navButton('finder','⌖',t('findCentre'))}${navButton('msp','₹',t('msp'))}${navButton('procurement-information','ⓘ',t('procurementInformation'))}${navButton('payment','◉',t('payment'))}${navButton('history','◫',t('history'))}${navButton('notifications','◌',t('notifications'))}${navButton('profile','◒',t('profile'))}`; }
function centreNav() { return `${navButton('centre-dashboard','▦',t('dashboard'))}${navButton('centre-info','▤',t('centreInfo'))}${navButton('bookings','☷',t('farmerBookings'))}${navButton('centre-payments','◉',t('paymentUpdates'))}${navButton('rates','₹',t('procurementRates'))}`; }

function renderFarmerPage() {
  const routes = { dashboard: renderFarmerDashboard, finder: renderFinder, 'centre-details': renderCentreDetails, msp: renderMsp, 'procurement-information': renderProcurementInformation, payment: renderPayment, history: renderHistory, notifications: renderNotifications, profile: renderProfile };
  return routes[ui.route]?.() || renderFarmerDashboard();
}
function pageHead(title, text, action = '') { return `<div class="page-head"><div><h1>${title}</h1><p>${text}</p></div>${action}</div>`; }
function disclaimer() { return `<div class="disclaimer">AgriConnect provides preliminary information and scheduling support. Final procurement eligibility, acceptance, quality assessment, procurement quantity and payment remain subject to the applicable procurement authority and official rules.</div>`; }
function sectionTitle(icon, title, text = '', orange = false) { return `<div class="section-card-title"><span class="title-icon ${orange ? 'orange' : ''}">${icon}</span><div><h2>${title}</h2>${text ? `<p>${text}</p>` : ''}</div></div>`; }

function renderFarmerDashboard() {
  const farmer = currentFarmer();
  const bookings = data.bookings.filter(item => item.farmerId === farmer.id);
  const active = bookings.find(item => item.status === 'Booked');
  const payments = data.payments.filter(item => item.farmerId === farmer.id);
  const totalQuantity = [...data.history.filter(item => item.farmerId === farmer.id), ...bookings.filter(item => item.status === 'Booked')].reduce((sum, item) => sum + Number(item.quantity), 0);
  const notices = data.notifications.filter(item => item.farmerId === farmer.id).slice().sort((a,b) => new Date(b.createdAt)-new Date(a.createdAt)).slice(0,3);
  return `<div class="page">${pageHead(`${t('dashboard')}, ${escapeHTML(farmer.name.split(' ')[0])}`, 'Here is a simple view of your procurement plan and recent updates.')}
    <section class="summary-grid"><div class="summary-card"><span class="summary-label">Total procurement quantity</span><strong>${totalQuantity} qtl</strong><span class="summary-note">Booked + recorded</span></div><div class="summary-card"><span class="summary-label">Estimated / recorded value</span><strong>${money([...data.history.filter(item => item.farmerId === farmer.id), ...bookings].reduce((sum, item) => sum + (item.amount || calculateRate(item.crop) * item.quantity), 0))}</strong><span class="summary-note">Configured MSP estimate</span></div><div class="summary-card"><span class="summary-label">Latest payment</span><strong>${payments[0] ? money(payments[0].amount) : '—'}</strong><span class="summary-note">${payments[0] ? 'Marked credited' : 'No payment update yet'}</span></div><div class="summary-card accent"><span class="summary-label">${t('currentBooking')}</span><strong>${active ? formatDate(active.date) : 'None'}</strong><span class="summary-note">${active ? active.slot : 'Find a suitable centre'}</span></div><div class="summary-card"><span class="summary-label">Unread notifications</span><strong>${data.notifications.filter(item => item.farmerId === farmer.id && !item.read).length}</strong><span class="summary-note">Important procurement updates</span></div></section>
    <section class="dashboard-grid"><div class="card">${sectionTitle('◷',t('currentBooking'), active ? 'Your booked visit and planning details.' : 'You have no active visit booked yet.')}${active ? renderActiveBooking(active) : `<div class="empty">⌖<b>No booking yet</b><span>Find a suitable procurement centre to plan your visit.</span><p><button class="button button-primary button-sm" data-route="finder">${t('findCentre')}</button></p></div>`}</div><div class="card">${sectionTitle('↗',t('quickActions'),'Start with what you need today.',true)}<div class="quick-actions"><button class="quick-action" data-route="finder"><span>⌖</span><b>${t('findCentre')}</b><span>Compare centres</span></button><button class="quick-action" data-route="msp"><span>₹</span><b>${t('viewMsp')}</b><span>Estimate value</span></button><button class="quick-action" data-route="procurement-information"><span>ⓘ</span><b>${t('procurementInformation')}</b><span>Rules & schedules</span></button><button class="quick-action" data-route="payment"><span>◉</span><b>${t('payment')}</b><span>Track updates</span></button><button class="quick-action" data-route="history"><span>◫</span><b>${t('history')}</b><span>See records</span></button></div></div><div class="card">${sectionTitle('◌',t('recentUpdates'),'Your latest AgriConnect notifications.')}<div class="activity-list">${notices.length ? notices.map(renderActivity).join('') : `<div class="empty">◌<b>No updates yet</b><span>Important booking and payment updates will appear here.</span></div>`}</div></div><div class="card">${sectionTitle('▣',t('support'),'The two details AgriConnect considers.')}<div class="activity-list"><div class="activity-item"><span class="activity-bullet">↗</span><div><strong>${t('distancePriority')}</strong><p>Travel burden may be considered when queue conditions are high.</p></div></div><div class="activity-item"><span class="activity-bullet">▣</span><div><strong>${t('nearbyStorage')}</strong><p>Crop-compatible facilities are shown only when capacity may be limited.</p></div></div></div></div></section>${disclaimer()}</div>`;
}
function renderActiveBooking(booking) { const centre = getCentre(booking.centreId); return `<div class="booking-status"><span class="booking-label">${t('booked')}</span><h3>${escapeHTML(centre?.name || 'Procurement Centre')}</h3><span class="small">${cropName(booking.crop)} · ${booking.quantity} quintals</span><div class="booking-details"><div><span>${t('date')}</span><b>${formatDate(booking.date)}</b></div><div><span>Time slot</span><b>${booking.slot}</b></div><div><span>${t('distance')}</span><b>${booking.distance.toFixed(1)} km</b></div></div></div>`; }
function renderActivity(item) { const icons = { welcome: '✦', storage: '▣', booking: '◷', payment: '₹', schedule: '◷' }; return `<div class="activity-item"><span class="activity-bullet">${icons[item.type] || '◌'}</span><div><strong>${escapeHTML(item.title)}</strong><p>${escapeHTML(item.body)}</p></div><time>${timeAgo(item.createdAt)}</time></div>`; }

function renderFinder() {
  const finder = ui.finder; const results = findCentres(finder); const top = results[0];
  return `<div class="page">${pageHead(t('findCentre'), 'Compare suitable centres using crop support, live operational conditions and approximate travel distance.')}<div class="search-layout"><aside class="card sticky-search">${sectionTitle('⌖','Plan your visit','Enter the crop and quantity you want to take to a centre.')}<form data-form="find-centres"><div class="form-field"><label>${t('crop')}</label><select name="crop">${cropOptions(finder.crop)}</select></div><div class="form-field"><label>${t('quantity')} <small class="muted">(quintals)</small></label><input name="quantity" type="number" min="1" value="${finder.quantity}" required /></div><div class="form-field"><label>${t('location')}</label><select name="location">${locationOptions(finder.locationKey)}</select></div><button class="button button-soft button-sm" type="button" data-action="use-location">⌖ ${t('useLocation')}</button><div class="location-status">✓ Using ${escapeHTML(locationLabel(finder.locationKey))} for approximate distance calculation.</div><button class="button button-primary" type="submit">${t('findSuitable')} <span>→</span></button><div class="form-note">Your location is used only to calculate an approximate distance. You can continue with manual location if browser permission is unavailable.</div></form></aside><section>${finder.searched ? `<div class="eligibility"><b>✓ ${t('eligibility')}: Eligible</b>${cropName(finder.crop)} is supported by one or more open centres. This is informational guidance, not official approval.</div><div class="result-intro"><div><h2>${results.length} suitable centre${results.length === 1 ? '' : 's'} found</h2><p>Ranked by crop support, slots, queue, capacity and approximate distance — not distance alone.</p></div>${top ? badge('available',`${t('recommended')}: ${top.shortName}`) : ''}</div><div class="centre-list">${results.map((entry, index) => renderCentreCard(entry, index === 0)).join('') || `<div class="card empty">⌖<b>No suitable centres are available</b><span>Try another crop or check again later for an available slot.</span></div>`}</div>` : ''}</section></div>${disclaimer()}</div>`;
}
function cropOptions(selected) { return Object.keys(cropTranslations).map(crop => `<option value="${crop}" ${crop === selected ? 'selected' : ''}>${cropName(crop)}</option>`).join(''); }
function locationOptions(selected) { const locations = { browser: ['Current browser location', ui.finder.coordinates], nandigama: ['Nandigama (manual location)',{lat:16.771,lng:80.286}], vijayawada: ['Vijayawada (manual location)',{lat:16.506,lng:80.648}], guntur: ['Guntur (manual location)',{lat:16.306,lng:80.436}], raghavapuram: ['Raghavapuram (manual location)',{lat:16.780,lng:80.215}] }; return Object.entries(locations).map(([key, value]) => `<option value="${key}" ${key === selected ? 'selected' : ''}>${value[0]}</option>`).join(''); }
function locationLabel(key) { return ({ nandigama:'Nandigama', vijayawada:'Vijayawada', guntur:'Guntur', raghavapuram:'Raghavapuram' }[key] || 'your selected location'); }
function findCentres(finder) {
  return data.centres.filter(centre => centre.status === 'open' && centre.crops.includes(finder.crop)).map(centre => {
    const distance = haversine(finder.coordinates, {lat:centre.lat,lng:centre.lng});
    const score = (centre.slots * 14) - (centre.queue * 1.1) + Math.min(100, getAvailableHolding(centre)) * .08 - distance * .24 + (centre.queueCondition === 'low' ? 7 : centre.queueCondition === 'moderate' ? 3 : 0);
    return { ...centre, distance, score };
  }).sort((a,b) => b.score - a.score);
}
function renderCentreCard(entry, recommended) { return `<article class="card centre-card ${recommended ? 'recommended' : ''}">${recommended ? `<span class="recommendation-tag">★ ${t('recommended')}</span>` : ''}<div><h3>${escapeHTML(entry.name)}</h3><span class="centre-subtitle">${escapeHTML(entry.type)} · ${escapeHTML(entry.agency)}</span><div class="centre-stats"><div class="centre-stat">${t('distance')}<b>${entry.distance.toFixed(1)} km</b></div><div class="centre-stat">${t('availableSlots')}<b>${entry.slots}</b></div><div class="centre-stat">${t('currentQueue')}<b>${entry.queue} farmers</b></div><div class="centre-stat">${t('waitingTime')}<b>${entry.waiting}</b></div></div><div class="reason">${recommended ? `Recommended because it supports ${cropName(ui.finder.crop)}, has available slots and currently offers the strongest balance of queue, capacity and travel conditions.` : entry.slots ? `Supports ${cropName(ui.finder.crop)}. Its availability, queue and distance are shown to help you compare it.` : t('noSlots')}</div></div><div class="centre-card-side">${badge(entry.queueCondition)}<button class="button button-outline button-sm" data-action="view-centre" data-centre-id="${entry.id}">${t('viewCentre')}</button>${entry.slots ? `<button class="button button-primary button-sm" data-action="view-centre" data-centre-id="${entry.id}">${t('useSlot')}</button>` : `<button class="button button-soft button-sm" data-action="view-centre" data-centre-id="${entry.id}">${t('viewCentre')}</button>`}</div></article>`; }

function renderCentreDetails() {
  const centre = getCentre(ui.selectedCentreId) || data.centres[0]; const finder = ui.finder; const distance = haversine(finder.coordinates, {lat:centre.lat,lng:centre.lng}); const rate = calculateRate(finder.crop); const estimate = rate * finder.quantity; const storageNeeded = isStorageNeeded(centre, finder.quantity); const storage = storageNeeded ? storageSuggestions(centre, finder.crop, finder.quantity) : [];
  const slot = priority(centre, distance) === 'earlier' ? '10:00 AM – 11:00 AM' : '11:00 AM – 12:00 PM';
  return `<div class="page">${pageHead('Centre details', 'Review operational information and choose a visit time that works for you.', `<button class="button button-outline button-sm" data-route="finder">← ${t('findCentre')}</button>`)}<div class="detail-grid"><section><article class="card detail-title-card"><span class="eyebrow" style="color:#ffad74">${t('recommended')} centre details</span><h2>${escapeHTML(centre.name)}</h2><p class="muted">${escapeHTML(centre.type)} · ${escapeHTML(centre.agency)}</p><div class="detail-chip-row"><span class="detail-chip">⌖ ${distance.toFixed(1)} km away</span><span class="detail-chip">${centre.slots} ${t('availableSlots').toLowerCase()}</span><span class="detail-chip">${centre.schedule}</span></div></article><article class="card" style="margin-top:18px">${sectionTitle('▤','Centre information','Current operational information supplied by this centre.')}<div class="metric-grid"><div class="metric"><span>${t('currentQueue')}</span><strong>${centre.queue} farmers</strong>${badge(centre.queueCondition)}</div><div class="metric"><span>${t('waitingTime')}</span><strong>${centre.waiting}</strong><span class="status-note">Current estimate</span></div><div class="metric"><span>${t('availableSlots')}</span><strong>${centre.slots}</strong><span class="status-note">For listed schedule</span></div><div class="metric"><span>${t('schedule')}</span><strong>${centre.schedule.split('·')[0]}</strong><span class="status-note">${centre.schedule.split('·')[1] || ''}</span></div><div class="metric"><span>Supported crops</span><strong>${centre.crops.map(cropName).join(', ')}</strong></div><div class="metric"><span>Immediate holding</span><strong>${getAvailableHolding(centre)} qtl</strong><span class="status-note">Available of ${centre.holdingCapacity} qtl</span></div></div></article><article class="card recommend-card" style="margin-top:18px">${sectionTitle('↗',t('distancePriority'),'A transparent scheduling recommendation based on current conditions.')}<p class="recommend-copy">${translateDynamic('distance',priorityMessage(centre,distance))}</p><div class="recommend-score"><span>Travel + queue consideration</span><span class="score-line"><i style="width:${priority(centre,distance) === 'earlier' ? 87 : centre.queueCondition === 'moderate' ? 63 : 40}%"></i></span><strong>${priority(centre,distance) === 'earlier' ? 'Earlier suitable slot' : 'Balanced suggestion'}</strong></div></article>${storageNeeded ? renderStorage(centre, storage) : ''}</section><aside><article class="card">${sectionTitle('₹','MSP & estimated value','Configured demo rate; not a guaranteed final payment.',true)}<div class="metric-grid"><div class="metric"><span>Crop</span><strong>${cropName(finder.crop)}</strong></div><div class="metric"><span>Configured MSP</span><strong>${money(rate)} / qtl</strong></div><div class="metric"><span>${t('estimatedValue')}</span><strong>${money(estimate)}</strong></div></div></article><article class="card" style="margin-top:18px">${sectionTitle('◷',t('bookSlot'),`Suggested visit: ${slot}`)}${centre.slots ? `<form class="booking-form" data-form="prepare-booking"><div class="field-grid"><div class="form-field"><label>${t('date')}</label><input name="date" type="date" min="2026-09-15" value="2026-09-18" required /></div><div class="form-field"><label>Time slot</label><select name="slot"><option>${slot}</option><option>11:00 AM – 12:00 PM</option><option>12:00 PM – 1:00 PM</option><option>2:00 PM – 3:00 PM</option></select></div></div><div class="form-field"><label>${t('quantity')} (quintals)</label><input name="quantity" type="number" min="1" value="${finder.quantity}" required /></div><div class="booking-summary"><b>Booking summary</b><br>${escapeHTML(centre.shortName)} · ${cropName(finder.crop)} · ${distance.toFixed(1)} km<br>${t('estimatedValue')}: <b>${money(estimate)}</b></div><button class="button button-primary" type="submit">${t('confirm')} ${t('bookSlot')} <span>→</span></button></form>` : `<div class="empty">◷<b>${t('noSlots')}</b><span>Please compare another suitable centre for an available time.</span><p><button class="button button-primary button-sm" data-route="finder">${t('findCentre')}</button></p></div>`}</article></aside></div>${disclaimer()}</div>`;
}
function storageSuggestions(centre, crop, quantity) { return data.storages.filter(store => store.available && store.crops.includes(crop) && store.availableCapacity >= Math.min(quantity, 20)).map(store => ({...store, distance: haversine({lat:centre.lat,lng:centre.lng},{lat:store.lat,lng:store.lng})})).sort((a,b) => (b.availableCapacity >= quantity ? 10 : 0) - (a.availableCapacity >= quantity ? 10 : 0) || a.distance-b.distance).slice(0,3); }
function renderStorage(centre, storage) { return `<article class="card storage-card" style="margin-top:18px">${sectionTitle('▣',t('nearbyStorage'),`Immediate holding capacity is ${getAvailableHolding(centre)} quintals for your ${ui.finder.quantity}-quintal quantity.`,true)}<p class="recommend-copy">${translateDynamic('storage','Immediate holding capacity is limited. These crop-compatible facilities are ranked by availability, capacity and distance from the centre.')}</p>${storage.length ? `<div class="storage-list">${storage.map((item,index) => `<div class="storage-item"><div><h4>${index === 0 ? '★ ' : ''}${escapeHTML(item.name)}</h4><p>${escapeHTML(item.type)} · ${item.crops.map(cropName).join(', ')} · ${escapeHTML(item.address)}</p><p>Reason: ${index === 0 ? 'supports your crop, has suitable available capacity and is nearby.' : 'compatible with your crop and currently available.'}</p></div><div class="storage-side"><strong>${item.distance.toFixed(1)} km</strong><span>${item.availableCapacity} qtl available</span><br>${badge('available',t('available'))}</div></div>`).join('')}</div>` : `<p class="muted small">No compatible available storage facility is currently listed for this crop and quantity.</p>`}<p class="status-note">${t('storageOptional')}</p></article>`; }

function renderMsp() {
  const { crop, quantity, grade } = ui.msp; const rate = calculateRate(crop, grade); const selectedRate = data.rates.find(item => item.crop === crop && item.grade === grade) || data.rates.find(item => item.crop === crop);
  return `<div class="page">${pageHead(t('msp'), 'View configured prototype MSP information and calculate an estimated procurement value.')}<div class="msp-grid"><section class="card">${sectionTitle('₹','Configured MSP rates','Demo reference rates — not live government price information.',true)}<div class="msp-rates">${data.rates.map(item => `<div class="rate-row"><div><strong>${cropName(item.crop)} · ${escapeHTML(item.grade)}</strong><span>${escapeHTML(item.season)}</span></div><span class="rate-value">${money(item.rate)} / qtl</span></div>`).join('')}</div></section><section class="card">${sectionTitle('▤',t('estimatedValue'),'Quantity × applicable configured MSP.')}<form data-form="msp-calculator"><div class="form-field"><label>${t('crop')}</label><select name="crop">${cropOptions(crop)}</select></div><div class="form-field"><label>Grade / type</label><select name="grade">${data.rates.filter(item => item.crop === crop).map(item => `<option ${item.grade === grade ? 'selected' : ''}>${item.grade}</option>`).join('')}</select></div><div class="form-field"><label>${t('quantity')} (quintals)</label><input type="number" min="1" name="quantity" value="${quantity}" required /></div><button class="button button-soft button-sm" type="submit">Calculate estimate</button></form><div class="estimate-display"><span>${cropName(crop)} · ${selectedRate?.grade || grade} · ${money(rate)} / qtl</span><strong>${money(rate * quantity)}</strong><span>${quantity} quintals × ${money(rate)}. This is an estimate, not a guaranteed final payment.</span></div></section></div>${disclaimer()}</div>`;
}
function renderProcurementInformation() {
  const info = procurementInformation;
  return `<div class="page procurement-info-page">${pageHead(t('procurementInformation'), t('procurementInfoSubtitle'))}
    <section class="info-hero card"><div><span class="eyebrow">OFFICIAL REFERENCE GUIDE</span><h2>Clear information before you plan your visit.</h2><p>This page explains general procurement information. It does not confirm eligibility, centre availability or final procurement acceptance.</p></div><div class="info-hero-note"><span>ⓘ</span><p>${t('referenceOnly')}</p></div></section>
    <section class="card info-section">${sectionTitle('₹',t('mspInformation'),'Minimum Support Price (MSP) is a Government-announced minimum support price for notified crops.',true)}<p class="info-intro">MSP values can change by marketing season. Procurement at MSP is carried out through designated government procurement agencies and depends on the applicable procurement policy or scheme.</p><div class="info-reference-row"><span class="badge violet">${t('mspReference')}</span><span>MSP values are subject to change when the Government announces new rates.</span></div><div class="data-table-wrap"><table class="data-table info-table"><thead><tr><th>Crop</th><th>Grade / type</th><th>Marketing season</th><th>MSP reference</th></tr></thead><tbody>${info.msp.map(item => `<tr><td><strong>${item.crop}</strong></td><td>${item.grade}</td><td>${item.season}</td><td><strong class="rate-value">${money(item.rate)} / qtl</strong></td></tr>`).join('')}</tbody></table></div></section>
    <section class="info-grid"><article class="card info-section">${sectionTitle('▤',t('procurementRules'),'General information — rules can vary by crop, state, agency and season.')}<ul class="info-list">${info.rules.map(item => `<li>${item}</li>`).join('')}</ul></article><article class="card info-section">${sectionTitle('✓',t('eligibilityConditions'),'Eligibility is not automatic for every MSP procurement operation.',true)}<p class="info-intro">Eligibility and basic conditions can depend on:</p><ul class="info-list compact">${info.eligibility.map(item => `<li>${item}</li>`).join('')}</ul><div class="info-callout">Before visiting a procurement centre, farmers should verify the current requirements and procurement availability applicable to their crop, state and season.</div></article></section>
    <section class="card info-section">${sectionTitle('◷',t('procurementSchedules'),'Marketing seasons help explain when procurement operations are generally organised.')}<div class="season-timeline">${info.seasons.map((season, index) => `<article class="season-card"><span class="season-step">0${index + 1}</span><div><h3>${season.name}</h3><p class="season-period">${season.period}</p><p>${season.crops}</p></div></article>`).join('')}</div><div class="info-callout">Exact procurement dates, centre opening and closing dates should be verified for the farmer’s state, crop and procurement centre. Individual crops are not necessarily procured throughout the entire marketing season.</div></section>
    <section class="card info-section">${sectionTitle('→',t('procurementProcess'),'A simple overview of the official procurement journey.',true)}<ol class="process-list">${info.process.map((item, index) => `<li><span>${index + 1}</span><p>${item}</p></li>`).join('')}</ol><p class="status-note">This is informational only. It does not replace or change the AgriConnect booking process.</p></section>
    <section class="card info-important">${sectionTitle('!',t('importantNotes'),'Please keep these points in mind.',true)}<ul class="info-list">${info.importantNotes.map(item => `<li>${item}</li>`).join('')}</ul></section>
    <section class="card info-sources">${sectionTitle('↗',t('officialSources'),'Official Government of India pages used as the reference for this prototype.')}<p class="info-intro">This prototype does not fetch live government data. Check these official pages for current notifications and updates.</p><div class="source-links">${info.sources.map(source => `<a href="${source.url}" target="_blank" rel="noopener noreferrer"><span>↗</span>${escapeHTML(source.label)}</a>`).join('')}</div></section>${disclaimer()}</div>`;
}
function renderPayment() {
  const farmer = currentFarmer(); const payments = data.payments.filter(item => item.farmerId === farmer.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  return `<div class="page">${pageHead(t('paymentTracking'), 'Payment updates entered by the procurement centre for your own bookings only.')}<section class="card">${sectionTitle('◉',t('payment'),'AgriConnect does not access bank accounts.',true)}${payments.length ? `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>${t('date')}</th><th>Centre</th><th>${t('crop')}</th><th>${t('quantity')}</th><th>${t('amount')}</th><th>${t('status')}</th></tr></thead><tbody>${payments.map(payment => { const booking=data.bookings.find(item=>item.id===payment.bookingId); const centre=getCentre(payment.centreId); return `<tr><td>${formatDate(payment.date)}</td><td>${escapeHTML(centre?.shortName || 'Procurement centre')}</td><td>${cropName(booking?.crop || payment.crop)}</td><td>${booking?.quantity || payment.quantity} qtl</td><td><strong>${money(payment.amount)}</strong></td><td>${badge('credited',t('paymentCredited'))}</td></tr>`; }).join('')}</tbody></table></div>` : `<div class="empty">◉<b>No payment update yet</b><span>When an authorised centre operator marks a payment as credited, it will appear here.</span></div>`}<div class="disclaimer">A credited status means the procurement centre has recorded the update. Please check your respective bank account. AgriConnect does not connect to or verify bank accounts.</div></section></div>`;
}
function renderHistory() {
  const farmer = currentFarmer(); const records = data.history.filter(item => item.farmerId === farmer.id).sort((a,b)=>new Date(b.date)-new Date(a.date)); const bookings = data.bookings.filter(item => item.farmerId === farmer.id && item.status === 'Booked');
  return `<div class="page">${pageHead(t('history'), 'Your procurement records and active bookings — visible only to you.')}<section class="card">${sectionTitle('◫',t('history'),'Recorded procurement and payment information.')}<div class="data-table-wrap"><table class="data-table"><thead><tr><th>${t('date')}</th><th>${t('crop')}</th><th>${t('quantity')}</th><th>Centre</th><th>${t('amount')}</th><th>${t('status')}</th></tr></thead><tbody>${[...records, ...bookings].length ? [...records,...bookings].map(record=>{const centre=getCentre(record.centreId);return `<tr><td>${formatDate(record.date)}</td><td>${cropName(record.crop)}</td><td>${record.quantity} qtl</td><td>${escapeHTML(centre?.shortName || 'Procurement centre')}</td><td>${money(record.amount || record.quantity * calculateRate(record.crop))}</td><td>${badge(record.status === 'Payment Credited' ? 'credited' : 'booked', record.status === 'Payment Credited' ? t('paymentCredited') : t('booked'))}</td></tr>`;}).join('') : `<tr><td colspan="6"><div class="empty">◫<b>No procurement history yet</b><span>Your completed procurement records will appear here.</span></div></td></tr>`}</tbody></table></div></section></div>`;
}
function renderNotifications() {
  const farmer = currentFarmer(); const notices = data.notifications.filter(item => item.farmerId === farmer.id).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)); const icons = { welcome:'✦', storage:'▣', booking:'◷', payment:'₹', schedule:'◷' };
  return `<div class="page">${pageHead(t('notifications'), 'Important booking, schedule, storage and payment updates.', `<button class="button button-outline button-sm" data-action="mark-read">${t('markAllRead')}</button>`)}<section class="notification-list">${notices.length ? notices.map(item=>`<article class="notification-card ${item.read ? '' : 'unread'}"><span class="notification-icon">${icons[item.type]||'◌'}</span><div><h3>${escapeHTML(item.title)}${!item.read ? '<span class="unread-pip"></span>' : ''}</h3><p>${escapeHTML(item.body)}</p></div><time>${timeAgo(item.createdAt)}</time></article>`).join('') : `<div class="card empty">◌<b>No notifications</b><span>Important updates will appear here.</span></div>`}</section></div>`;
}
function renderProfile() {
  const farmer = currentFarmer();
  return `<div class="page">${pageHead(t('profile'), 'Keep your farmer details and preferred language up to date.')}<div class="profile-layout"><aside class="card profile-card"><div class="profile-big-avatar">${initials(farmer.name)}</div><h2>${escapeHTML(farmer.name)}</h2><p>${escapeHTML(farmer.village)}, ${escapeHTML(farmer.district)}</p><span class="profile-id">${farmer.farmerId}</span><p class="small" style="margin-top:17px">Your Farmer ID is internal to AgriConnect and cannot be changed.</p></aside><section class="card">${sectionTitle('◒','Farmer details','Update the details you use to plan procurement visits.')}<form data-form="save-profile"><div class="field-grid"><div class="form-field"><label>${t('farmerName')}</label><input name="name" value="${escapeHTML(farmer.name)}" required /></div><div class="form-field"><label>${t('mobileNumber')}</label><input value="${escapeHTML(farmer.mobile)}" disabled /></div><div class="form-field"><label>${t('village')}</label><input name="village" value="${escapeHTML(farmer.village)}" required /></div><div class="form-field"><label>${t('district')}</label><input name="district" value="${escapeHTML(farmer.district)}" required /></div><div class="form-field"><label>${t('language')}</label><select name="language">${languageOptions(farmer.language)}</select></div><div class="form-field"><label>Farmer ID</label><input value="${farmer.farmerId}" disabled /></div></div><div class="settings-footer"><button class="button button-primary" type="submit">${t('saveChanges')}</button></div></form></section></div></div>`;
}

function renderOperatorPage() {
  const routes = { 'centre-dashboard':renderCentreDashboard, 'centre-info':renderCentreInfo, bookings:renderCentreBookings, 'centre-payments':renderCentrePayments, rates:renderRates };
  return routes[ui.route]?.() || renderCentreDashboard();
}
function centreBookings(centreId = currentCentre()?.id) { return data.bookings.filter(item => item.centreId === centreId).sort((a,b) => b.distance-a.distance); }
function renderCentreDashboard() {
  const centre = currentCentre(); const bookings = centreBookings(); const credited = data.payments.filter(item=>item.centreId===centre.id).length;
  return `<div class="page">${pageHead(`${t('dashboard')}, ${escapeHTML(centre.shortName)}`, 'Manage operational information, farmer bookings and payment-credit updates for your own centre.')}<section class="operator-metrics"><div class="summary-card accent"><span class="summary-label">${t('status')}</span><strong>${t(centre.status)}</strong><span class="summary-note">Centre operational state</span></div><div class="summary-card"><span class="summary-label">${t('availableSlots')}</span><strong>${centre.slots}</strong><span class="summary-note">For current schedule</span></div><div class="summary-card"><span class="summary-label">${t('currentQueue')}</span><strong>${centre.queue}</strong><span class="summary-note">${t(centre.queueCondition)} condition</span></div><div class="summary-card"><span class="summary-label">Payments credited</span><strong>${credited}</strong><span class="summary-note">For your centre only</span></div></section><div class="operational-notice"><div><b>Distance-aware queue view is active</b>Your booking queue highlights farmers travelling the farthest when conditions are high. It is planning support, not an official priority policy.</div><button class="button button-outline button-sm" data-route="bookings">View bookings</button></div><section class="dashboard-grid"><div class="card">${sectionTitle('☷','Recent farmer bookings',`${bookings.length} booking${bookings.length===1?'':'s'} for your centre.`)}${renderBookingTable(bookings.slice(0,5),false)}</div><div class="card">${sectionTitle('▤','Centre at a glance','Information currently shown to farmers.')}<div class="activity-list"><div class="activity-item"><span class="activity-bullet">◷</span><div><strong>${centre.schedule}</strong><p>Current procurement schedule</p></div></div><div class="activity-item"><span class="activity-bullet">◉</span><div><strong>${centre.waiting} waiting time</strong><p>${centre.queue} farmers · ${t(centre.queueCondition)} queue</p></div></div><div class="activity-item"><span class="activity-bullet">▣</span><div><strong>${getAvailableHolding(centre)} qtl immediate holding</strong><p>of ${centre.holdingCapacity} quintals total capacity</p></div></div></div><p style="margin:17px 0 0"><button class="button button-soft button-sm" data-route="centre-info">${t('updateOperations')}</button></p></div></section></div>`;
}
function renderCentreInfo() {
  const centre = currentCentre();
  return `<div class="page">${pageHead(t('centreInfo'), 'Update operational information. Farmers will see these conditions when comparing centres.')}<section class="card">${sectionTitle('▤','Operational details','Centre operators can update operational information, not official MSP rates.')}<form data-form="save-centre"><div class="setting-grid"><div class="form-field"><label>${t('centreName')}</label><input name="name" value="${escapeHTML(centre.name)}" required /></div><div class="form-field"><label>${t('status')}</label><select name="status"><option value="open" ${centre.status==='open'?'selected':''}>${t('open')}</option><option value="closed" ${centre.status==='closed'?'selected':''}>${t('closed')}</option></select></div><div class="form-field"><label>${t('availableSlots')}</label><input name="slots" type="number" min="0" value="${centre.slots}" required /></div><div class="form-field"><label>${t('currentQueue')} (farmers)</label><input name="queue" type="number" min="0" value="${centre.queue}" required /></div><div class="form-field"><label>Queue condition</label><select name="queueCondition"><option value="low" ${centre.queueCondition==='low'?'selected':''}>${t('low')}</option><option value="moderate" ${centre.queueCondition==='moderate'?'selected':''}>${t('moderate')}</option><option value="high" ${centre.queueCondition==='high'?'selected':''}>${t('high')}</option></select></div><div class="form-field"><label>${t('waitingTime')}</label><input name="waiting" value="${escapeHTML(centre.waiting)}" required /></div><div class="form-field full"><label>${t('schedule')}</label><input name="schedule" value="${escapeHTML(centre.schedule)}" required /></div><div class="form-field"><label>Holding capacity (quintals)</label><input name="holdingCapacity" type="number" min="0" value="${centre.holdingCapacity}" required /></div><div class="form-field"><label>Current holding (quintals)</label><input name="currentHolding" type="number" min="0" value="${centre.currentHolding}" required /></div></div><div class="settings-footer"><button class="button button-primary" type="submit">${t('saveChanges')}</button></div></form></section><div class="disclaimer">Operational updates influence centre recommendations and storage support. They do not change official procurement eligibility or MSP.</div></div>`;
}
function renderBookingTable(bookings, showActions = true) { return bookings.length ? `<div class="data-table-wrap"><table class="data-table"><thead><tr><th>${t('farmer')}</th><th>${t('crop')}</th><th>${t('quantity')}</th><th>${t('distance')}</th><th>${t('date')} / slot</th><th>Recommendation</th><th>${t('status')}</th>${showActions?'<th></th>':''}</tr></thead><tbody>${bookings.map(item=>{const early=priority(currentCentre(), item.distance)==='earlier';return `<tr><td><div class="person-cell"><span class="table-avatar">${initials(item.farmerName)}</span><span><strong>${escapeHTML(item.farmerName)}</strong><br><small class="muted">${escapeHTML(item.farmerId)}</small></span></div></td><td>${cropName(item.crop)}</td><td>${item.quantity} qtl</td><td><strong>${item.distance.toFixed(1)} km</strong></td><td>${formatDate(item.date)}<br><small class="muted">${item.slot}</small></td><td>${badge(early?'violet':'moderate',early?'Earlier suitable':'Normal')}</td><td>${badge(item.status==='Payment Credited'?'credited':'booked',item.status==='Payment Credited'?t('paymentCredited'):t('booked'))}</td>${showActions?`<td>${item.status==='Booked'?`<button class="button button-soft button-sm" data-action="mark-payment" data-booking-id="${item.id}">Mark credited</button>`:'—'}</td>`:''}</tr>`;}).join('')}</tbody></table></div>` : `<div class="empty">☷<b>No bookings for this centre</b><span>New bookings at your centre will appear here.</span></div>`; }
function renderCentreBookings() { const centre=currentCentre(); const bookings=centreBookings(); return `<div class="page">${pageHead(t('farmerBookings'), 'Bookings below belong only to your centre. Distance is calculated from the stored farmer and centre coordinates.')}<section class="card">${sectionTitle('↗','Distance-aware booking queue','Long-distance farmers are highlighted only when the current queue condition is high.')}<div class="operational-notice"><div><b>${centre.queue} farmers · ${t(centre.queueCondition)} queue</b>When queue conditions are high, a farmer travelling 18 km or more is shown with an earlier suitable slot recommendation.</div><button class="button button-outline button-sm" data-route="centre-info">Update queue</button></div>${renderBookingTable(bookings,true)}</section></div>`; }
function renderCentrePayments() { const bookings=centreBookings(); return `<div class="page">${pageHead(t('paymentUpdates'), 'Mark payment credited only after the authorised procurement process has completed.')}<section class="card">${sectionTitle('◉',t('paymentUpdates'),'Updates are tied to the correct farmer, booking and centre.',true)}${renderBookingTable(bookings,true)}<div class="disclaimer">Marking a payment credited creates a payment record, procurement history entry and notification only for the farmer connected to that booking. Farmers are asked to check their own bank account.</div></section></div>`; }
function renderRates() { return `<div class="page">${pageHead(t('procurementRates'), 'Configured rate information is read-only for centre operators.')}<section class="card">${sectionTitle('₹','Configured procurement rate information','Ordinary centre operators cannot change official Government MSP.',true)}<div class="data-table-wrap"><table class="data-table"><thead><tr><th>${t('crop')}</th><th>Grade / type</th><th>${t('season')}</th><th>Configured rate</th></tr></thead><tbody>${data.rates.map(rate=>`<tr><td><strong>${cropName(rate.crop)}</strong></td><td>${rate.grade}</td><td>${rate.season}</td><td><strong>${money(rate.rate)} / qtl</strong></td></tr>`).join('')}</tbody></table></div></section></div>`; }

function renderModal() {
  if (!ui.modal) return '';
  if (ui.modal.type === 'booking') {
    const { centre, date, slot, quantity, distance } = ui.modal; const rate = calculateRate(ui.finder.crop);
    return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="booking-modal-title"><div class="confirm-icon">◷</div><h2 id="booking-modal-title">Confirm your booking</h2><p>Please check these details before confirming your procurement visit.</p><div class="booking-summary" style="margin-top:18px"><b>${escapeHTML(centre.name)}</b><br>${cropName(ui.finder.crop)} · ${quantity} quintals<br>${formatDate(date)} · ${slot}<br>Approx. distance: ${distance.toFixed(1)} km<br>${t('estimatedValue')}: <b>${money(rate * quantity)}</b></div><div class="modal-actions"><button class="button button-ghost" data-action="close-modal">${t('cancel')}</button><button class="button button-primary" data-action="confirm-booking">${t('confirm')} ${t('bookSlot')}</button></div></section></div>`;
  }
  if (ui.modal.type === 'payment') {
    const booking = ui.modal.booking; const centre = currentCentre(); const amount = booking.quantity * calculateRate(booking.crop);
    return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="payment-modal-title"><div class="confirm-icon">₹</div><h2 id="payment-modal-title">Mark payment credited?</h2><p>This creates a payment update, procurement history record and notification for the correct farmer.</p><div class="booking-summary" style="margin-top:18px"><b>${escapeHTML(booking.farmerName)}</b><br>${cropName(booking.crop)} · ${booking.quantity} quintals<br>${escapeHTML(centre.shortName)} · ${formatDate(booking.date)}<br>Configured amount: <b>${money(amount)}</b></div><div class="modal-actions"><button class="button button-ghost" data-action="close-modal">${t('cancel')}</button><button class="button button-primary" data-action="confirm-payment">${t('confirm')} ${t('paymentCredited')}</button></div></section></div>`;
  }
  return '';
}

function toast(message, type = 'success') {
  const region = document.getElementById('toast-region');
  if (!region) return;
  const item = document.createElement('div'); item.className = `toast ${type}`; item.textContent = message; region.appendChild(item); setTimeout(() => item.remove(), 3700);
}
function navigate(route) { ui.route = route; ui.mobileSidebar = false; render(); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function setLanguage(value) { const user=currentUser(); if (user) { user.language=value; persist(); } render(); toast(t('languageChanged')); }
function addNotification(farmerId, type, title, body) { data.notifications.push({ id:`notice-${Date.now()}-${Math.random().toString(36).slice(2,6)}`, farmerId, type, title, body, read:false, createdAt:new Date().toISOString() }); }

document.addEventListener('click', event => {
  const target = event.target.closest('[data-action], [data-route]');
  if (!target) return;
  const action = target.dataset.action;
  if (target.dataset.route) { navigate(target.dataset.route); return; }
  if (!action) return;
  if (action === 'go-home') { event.preventDefault(); ui.session=null; ui.route='home'; render(); return; }
  if (action === 'start-auth') { ui.route='auth'; ui.auth={role:target.dataset.role,mode:target.dataset.mode,step:1,mobile:''}; render(); return; }
  if (action === 'toggle-auth-mode') { ui.auth.mode=ui.auth.mode==='login'?'register':'login'; ui.auth.step=1; render(); return; }
  if (action === 'switch-auth-role') { ui.auth.role=ui.auth.role==='farmer'?'centre':'farmer'; ui.auth.step=1; render(); return; }
  if (action === 'auth-back') { ui.auth.step=1; render(); return; }
  if (action === 'toggle-menu') { ui.mobileSidebar=!ui.mobileSidebar; render(); return; }
  if (action === 'logout') { ui.session=null; ui.route='home'; ui.modal=null; render(); toast('You have been logged out.'); return; }
  if (action === 'use-location') { requestLocation(); return; }
  if (action === 'view-centre') { ui.selectedCentreId=target.dataset.centreId; navigate('centre-details'); return; }
  if (action === 'mark-read') { const farmer=currentFarmer(); data.notifications.filter(item=>item.farmerId===farmer.id).forEach(item=>item.read=true); persist(); render(); toast('All notifications marked as read.'); return; }
  if (action === 'close-modal') { ui.modal=null; render(); return; }
  if (action === 'confirm-booking') { confirmBooking(); return; }
  if (action === 'mark-payment') { const booking=data.bookings.find(item=>item.id===target.dataset.bookingId); if (booking) { ui.modal={type:'payment',booking}; render(); } return; }
  if (action === 'confirm-payment') { confirmPayment(); return; }
});

document.addEventListener('change', event => {
  if (event.target.matches('[data-home-language]')) { ui.homeLanguage=event.target.value; render(); return; }
  if (event.target.matches('[data-app-language]')) { setLanguage(event.target.value); return; }
});
document.addEventListener('submit', event => {
  const form = event.target; if (!form.dataset.form) return; event.preventDefault(); const values = Object.fromEntries(new FormData(form).entries());
  if (form.dataset.form === 'send-otp') { const mobile = String(values.mobile || '').replace(/\D/g,''); if (mobile.length !== 10) { toast('Enter a valid 10-digit mobile number.', 'warning'); return; } ui.auth.mobile=mobile; ui.auth.step=2; render(); toast('Demo OTP is ready to verify.'); return; }
  if (form.dataset.form === 'verify-otp') { if (values.otp !== '123456') { toast('Use the demo OTP 123456 to continue.', 'warning'); return; } finishOtpLogin(); return; }
  if (form.dataset.form === 'register-farmer') { registerFarmer(values); return; }
  if (form.dataset.form === 'register-centre') { registerCentre(values); return; }
  if (form.dataset.form === 'find-centres') { const amount=Number(values.quantity); if (!Number.isFinite(amount) || amount <= 0) { toast('Enter a quantity greater than zero.', 'warning'); return; } ui.finder.crop=values.crop; ui.finder.quantity=amount; ui.finder.locationKey=values.location; ui.finder.coordinates=coordinatesForLocation(values.location); ui.finder.searched=true; render(); toast('Suitable centres updated using your selected details.'); return; }
  if (form.dataset.form === 'prepare-booking') { const quantity=Number(values.quantity); if (!Number.isFinite(quantity) || quantity<=0) { toast('Enter a valid quantity.', 'warning'); return; } const centre=getCentre(ui.selectedCentreId); const farmer=currentFarmer(); const duplicate=data.bookings.some(item=>item.farmerId===farmer.id && item.centreId===centre.id && item.crop===ui.finder.crop && item.date===values.date && item.slot===values.slot && item.status==='Booked'); if (duplicate) { toast('You already have a booking for this centre, crop and time.', 'warning'); return; } ui.modal={type:'booking',centre,date:values.date,slot:values.slot,quantity,distance:haversine(ui.finder.coordinates,{lat:centre.lat,lng:centre.lng})}; render(); return; }
  if (form.dataset.form === 'msp-calculator') { const quantity=Number(values.quantity); if (!Number.isFinite(quantity)||quantity<=0) { toast('Enter a quantity greater than zero.', 'warning'); return; } ui.msp={crop:values.crop,grade:values.grade,quantity}; render(); return; }
  if (form.dataset.form === 'save-profile') { const farmer=currentFarmer(); Object.assign(farmer,{name:values.name.trim(),village:values.village.trim(),district:values.district.trim(),language:values.language}); persist(); render(); toast('Profile saved.'); return; }
  if (form.dataset.form === 'save-centre') { saveCentre(values); return; }
});

function coordinatesForLocation(key) { return ({ nandigama:{lat:16.771,lng:80.286}, vijayawada:{lat:16.506,lng:80.648}, guntur:{lat:16.306,lng:80.436}, raghavapuram:{lat:16.780,lng:80.215} }[key] || {lat:16.771,lng:80.286}); }
function requestLocation() {
  if (!navigator.geolocation) { toast('Location is unavailable in this browser. Choose a manual location instead.', 'warning'); return; }
  toast('Requesting your browser location…');
  navigator.geolocation.getCurrentPosition(position => { ui.finder.coordinates={lat:position.coords.latitude,lng:position.coords.longitude}; ui.finder.locationKey='browser'; ui.finder.searched=true; render(); toast('Current location applied. Distances are approximate.'); }, () => { toast('Location permission was not available. You can use a manual location instead.', 'warning'); }, { enableHighAccuracy:false, timeout:9000, maximumAge:120000 });
}
function finishOtpLogin() {
  const existing=data.users.find(user=>user.role===ui.auth.role && user.mobile===ui.auth.mobile);
  if (ui.auth.mode==='register') { ui.auth.step=3; render(); return; }
  let user=existing;
  if (!user && ui.auth.role==='farmer') { user=data.users.find(item=>item.id==='farmer-demo'); toast('Demo farmer account opened for this prototype.'); }
  if (!user && ui.auth.role==='centre') { user=data.users.find(item=>item.id==='centre-demo'); toast('Demo centre account opened for this prototype.'); }
  ui.session={role:user.role,userId:user.id}; ui.route=user.role==='farmer'?'dashboard':'centre-dashboard'; render(); toast(`Welcome, ${user.name || user.operatorName}.`);
}
function registerFarmer(values) {
  const id=`farmer-${Date.now()}`; const user={id,role:'farmer',mobile:ui.auth.mobile,name:values.name.trim(),village:values.village.trim(),district:values.district.trim(),language:values.language,farmerId:`AGF${String(Math.floor(100000+Math.random()*899999))}`,coordinates:coordinatesForLocation('nandigama')}; data.users.push(user); persist(); ui.session={role:'farmer',userId:id}; ui.route='dashboard'; render(); toast('Farmer account created successfully.');
}
function registerCentre(values) {
  const centreId=`centre-${Date.now()}`; const operatorId=`operator-${Date.now()}`; const centre={id:centreId,name:values.centreName.trim(),shortName:values.centreName.trim().split(' ')[0],type:values.centreType,agency:'Prototype Procurement Agency',lat:16.77,lng:80.29,crops:['paddy','wheat'],slots:0,queue:0,queueCondition:'low',waiting:'10–20 min',schedule:'Mon–Fri · 9:00 AM–4:00 PM',status:'open',holdingCapacity:500,currentHolding:0,operatorId}; const user={id:operatorId,role:'centre',mobile:ui.auth.mobile,name:values.operatorName.trim(),operatorName:values.operatorName.trim(),centreId,village:values.village.trim(),district:values.district.trim(),language:'en'}; data.centres.push(centre); data.users.push(user); persist(); ui.session={role:'centre',userId:operatorId}; ui.route='centre-dashboard'; render(); toast('Centre account created successfully.');
}
function confirmBooking() {
  const { centre, date, slot, quantity, distance }=ui.modal; const farmer=currentFarmer(); const booking={id:`booking-${Date.now()}`,farmerId:farmer.id,farmerName:farmer.name,farmerMobile:farmer.mobile,centreId:centre.id,crop:ui.finder.crop,quantity,distance,date,slot,status:'Booked',createdAt:new Date().toISOString()}; data.bookings.push(booking); centre.slots=Math.max(0,centre.slots-1); centre.queue+=1; addNotification(farmer.id,'booking','Your procurement slot is booked',`${cropName(booking.crop)} collection at ${centre.name} on ${formatDate(date)}, ${slot}.`); if (isStorageNeeded(centre,quantity)) addNotification(farmer.id,'storage','Nearby storage recommended',`Immediate holding capacity is limited. A suitable storage option is listed near ${centre.shortName}.`); persist(); ui.modal=null; ui.route='dashboard'; render(); toast('Your procurement slot has been booked.');
}
function saveCentre(values) {
  const centre=currentCentre(); Object.assign(centre,{name:values.name.trim(),status:values.status,slots:Math.max(0,Number(values.slots)),queue:Math.max(0,Number(values.queue)),queueCondition:values.queueCondition,waiting:values.waiting.trim(),schedule:values.schedule.trim(),holdingCapacity:Math.max(0,Number(values.holdingCapacity)),currentHolding:Math.max(0,Number(values.currentHolding))}); if (centre.currentHolding>centre.holdingCapacity) centre.currentHolding=centre.holdingCapacity; persist(); render(); toast('Centre operations updated. Farmer recommendations now use these conditions.');
}
function confirmPayment() {
  const booking=ui.modal.booking; const amount=booking.quantity*calculateRate(booking.crop); const today=new Date().toISOString().slice(0,10); booking.status='Payment Credited'; const payment={id:`payment-${Date.now()}`,farmerId:booking.farmerId,bookingId:booking.id,centreId:booking.centreId,crop:booking.crop,quantity:booking.quantity,amount,date:today,createdAt:new Date().toISOString()}; data.payments.push(payment); data.history.push({id:`history-${Date.now()}`,farmerId:booking.farmerId,bookingId:booking.id,centreId:booking.centreId,crop:booking.crop,quantity:booking.quantity,amount,date:today,status:'Payment Credited'}); const centre=currentCentre(); addNotification(booking.farmerId,'payment','Payment has been marked as credited',`${money(amount)} has been marked as credited for your ${cropName(booking.crop)} procurement at ${centre.shortName}. Please check your bank account.`); persist(); ui.modal=null; render(); toast(`Payment marked as credited for ${booking.farmerName}.`);
}

render();
